def fill_gaps_simple(grid, bg=8, fill=2):
    """Fill gaps in horizontal sequences between same non-bg values"""
    rows = [list(r) for r in grid]
    for r in range(len(rows)):
        for c in range(len(rows[r]) - 2):
            if rows[r][c] == rows[r][c+2] != bg and rows[r][c+1] == bg:
                rows[r][c+1] = fill
        # Fix gaps in what was previously filled
        for c in range(len(rows[r]) - 2):
            if rows[r][c] == rows[r][c+2] != bg and rows[r][c+1] == bg:
                rows[r][c+1] = fill
    return rows

